<script setup>
import ERPChatter from '../components/erp/ERPChatter.vue'
import AppIcon from '../components/AppIcon.vue'
import { useAuthStore } from '../stores/auth'
import { erp, money, useWorkspace } from '../composables/erp'
const auth = useAuthStore()
const { data, error, loading, refresh } = useWorkspace(id => erp(id, 'dashboard/'))
const stages = [['new', 'New'], ['qualified', 'Qualified'], ['proposition', 'Proposition'], ['won', 'Won'], ['lost', 'Lost']]
function pipeline(stage) { return data.value?.pipeline.find(item => item.stage === stage) || { count: 0, value: 0 } }
function width(stage) { return `${Math.max(3, Number(pipeline(stage).value) / Math.max(...data.value.pipeline.map(item => Number(item.value)), 1) * 100)}%` }
</script>
<template>
  <section class="business-page"><div class="control-panel"><div class="control-title"><span class="dashboard-kicker">WORKSPACE OVERVIEW</span><h1>{{ auth.activeCompany?.name || 'Your business' }}</h1><span class="muted">A live summary of the work that needs attention.</span></div><button class="button-secondary" :disabled="loading" @click="refresh"><AppIcon name="connection" />{{ loading ? 'Refreshing' : 'Refresh' }}</button></div><div class="workspace-content dashboard-content">
    <p v-if="!auth.activeCompanyId" class="empty-state">Create your first company to get started. <RouterLink to="/companies" class="text-link">Open companies →</RouterLink></p>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="loading" class="loading-state" role="status">Loading your overview…</p>
    <template v-if="data">
      <section class="dashboard-summary" aria-labelledby="business-summary-title"><div><span class="dashboard-kicker">TODAY'S PRIORITIES</span><h2 id="business-summary-title">Keep your business moving</h2><p>Review live sales, cash flow, and outstanding work from one place.</p></div><div class="dashboard-shortcuts" aria-label="Quick actions"><RouterLink to="/sales"><AppIcon name="trend" />Sales</RouterLink><RouterLink to="/inventory"><AppIcon name="box" />Inventory</RouterLink><RouterLink to="/tasks"><AppIcon name="project" />Tasks</RouterLink></div></section>
      <div class="metrics-grid"><RouterLink to="/sales" class="metric-card"><span class="metric-icon"><AppIcon name="trend" /></span><span>Confirmed sales</span><strong>{{ money(data.sales_total, data.currency) }}</strong><small>{{ data.quotations }} open quotations <AppIcon name="arrow" /></small></RouterLink><RouterLink to="/crm" class="metric-card purple"><span class="metric-icon"><AppIcon name="pipeline" /></span><span>Pipeline value</span><strong>{{ money(data.pipeline_value, data.currency) }}</strong><small>{{ data.open_opportunities }} open opportunities <AppIcon name="arrow" /></small></RouterLink><RouterLink to="/invoicing" class="metric-card teal"><span class="metric-icon"><AppIcon name="receipt" /></span><span>Customer receivables</span><strong>{{ money(data.receivable, data.currency) }}</strong><small>Issued invoices · remaining balance <AppIcon name="arrow" /></small></RouterLink><RouterLink to="/invoicing" class="metric-card orange"><span class="metric-icon"><AppIcon name="cart" /></span><span>Vendor payables</span><strong>{{ money(data.payable, data.currency) }}</strong><small>Issued vendor bills · remaining balance <AppIcon name="arrow" /></small></RouterLink></div>
      <div class="dashboard-columns"><section class="panel pipeline-chart"><div class="section-heading"><h2>Opportunity pipeline</h2><RouterLink to="/crm" class="text-link">Open CRM →</RouterLink></div><RouterLink v-for="[stage, label] in stages" :key="stage" :to="`/crm?stage=${stage}`" class="pipeline-row"><span>{{ label }} <small>{{ pipeline(stage).count }}</small></span><div class="bar-track"><div class="bar-fill" :class="stage" :style="{ width: width(stage) }"></div></div><strong>{{ money(pipeline(stage).value, data.currency) }}</strong></RouterLink></section><section class="panel operational-panel"><h2>Keep things moving</h2><RouterLink to="/contacts"><span>Active contacts</span><strong>{{ data.contacts }}</strong></RouterLink><RouterLink to="/inventory"><span>Active products</span><strong>{{ data.products }}</strong></RouterLink><RouterLink to="/inventory"><span>Products at low stock</span><strong class="warning-label">{{ data.low_stock }}</strong></RouterLink><RouterLink to="/tasks"><span>Open tasks</span><strong>{{ data.open_tasks }}</strong></RouterLink><RouterLink to="/tasks"><span>Overdue tasks</span><strong class="warning-label">{{ data.overdue_tasks }}</strong></RouterLink></section></div>
      <div class="dashboard-columns"><section class="panel"><div class="section-heading"><h2>Recent orders</h2><RouterLink to="/sales" class="text-link">View sales →</RouterLink></div><div class="table-wrap" role="region" aria-label="Dashboard records" tabindex="0"><table v-if="data.recent_orders.length" class="data-table"><thead><tr><th>Reference</th><th>Partner</th><th>Total</th><th>Status</th></tr></thead><tbody><tr v-for="order in data.recent_orders" :key="order.id"><td><RouterLink :to="`${order.kind === 'sale' ? '/sales' : '/purchase'}/${order.id}`" class="text-link">{{ order.number }}</RouterLink></td><td>{{ order.contact_name }}</td><td>{{ money(order.total, order.currency) }}</td><td><span class="badge" :class="order.status">{{ order.status }}</span></td></tr></tbody></table><p v-else class="muted">Orders will appear here after you create your first quotation or RFQ.</p></div></section><ERPChatter class="panel activity-panel" :activities="data.activities" /></div>
    </template>
  </div></section>
</template>
